export type State<T> = {
    value: T | undefined;
    error: undefined;
} | {
    value: false;
    error: Error;
};
type Action<T> = {
    type: 'RESOLVE';
    value: T;
} | {
    type: 'REJECT';
    error: Error;
} | {
    type: 'RESET';
};
export default function useResolver<T>(resetKey?: unknown): [State<T>, React.Dispatch<Action<T>>];
export {};
